use xiom.io;

use xiom.string;
type Score = {
  value: Int;
  invariant: value >= 0;
}

fn Score.add(self, points: Int) -> Int
  requires: points >= 0;
{
  return self.value + points;
}

fn Score.deduct(self, points: Int) -> Int
  requires: points >= 0;
{
  let new_val = self.value - points;
  if new_val < 0 { return 0; }
  else { return new_val; }
}

fn main() -> Int {
  let s = Score { value: 100 };
  let after_add = s.add(50);
  io.println(to_string(after_add));
  let after_deduct = s.deduct(30);
  io.println(to_string(after_deduct));
  return 0;
}
